  "b2.itblock": "ଇନକମ୍ ଟ୍ୟାକ୍ସ ଡେପ୍ରିସିଏସନ, FY {fy}",
  "b2.itblockh": "ଆସେଟ୍ ବ୍ଲକ୍ ଅନୁସାରେ, କେବଳ ଇନକମ୍ ଟ୍ୟାକ୍ସ ରିଟର୍ଣ୍ଣ ପାଇଁ (ଖାତାରେ ପକାଯାଏ ନାହିଁ)।",
