  "ca.party": "Party",
  "ca.screen": "Screen",
  "ca.general": "General comment",
  "cv.h1": "Accountant viewer: open the books file your client sent",
  "cv.intro": "Your client packs their books for a period into one file and sends it to you on WhatsApp or by email. Open it here and read it: dues, parties, ledgers, day book, GST working, final accounts and every document. Search and filter, ask queries on any entry, and send your comments back as a small file. Free, no login, and nothing is uploaded: the file is read inside your browser.",
  "cv.drop": "Drop the .nsca file here",
  "cv.choose": "Choose the file",
  "cv.dropnote": "The file stays on this device. Nothing is saved here and you cannot change your client's books from here.",
  "cv.nav.home": "Overview",
  "cv.docs": "Documents",
  "cv.day": "Day book",
  "cv.fin": "Final accounts",
  "cv.gst": "GST working",
  "cv.cT": "Queries and comments",
  "cv.how.h": "How this works",
  "cv.how.1": "Your client opens Nivesh Sahayak, goes to My data, Send to your accountant, and chooses \"Make a file for my accountant\" for one business and period.",
  "cv.how.2": "They send you the file (ending .nsca) and a short check code in the same message.",
  "cv.how.3": "You open the file on this page. The page tells you whether the file is unchanged and lets you type the check code your client gave you to compare.",
  "cv.how.4": "Read the books, search, and press \"Add a query or comment\" on any document, day-book entry or screen. Everything you write stays in this browser.",
  "cv.how.5": "When you are done, open \"Queries and comments\" and send the small .nsca-comments file back. Your client loads it and sees each query beside the entry. They can reply, and you can load the replies here.",
  "cv.live.h": "A file hand-over, not a live login",
  "cv.live.p": "This is a file hand-over. You do not log in to your client's account and you do not see changes they make later. A live shared login would need a server that stores the books, and Nivesh Sahayak has none: the books stay on your client's device. For a newer period or after corrections, ask your client for a fresh file.",
  "cv.safe.h": "What is in the file, and what is not",
  "cv.safe.p": "Your client ticks what goes in. By default the file has the entries, parties and items of one business up to the end of the period. Quotations and orders, salary and staff records, phone numbers and e-mail addresses, and the business's bank account details are left out unless your client ticks them. Pictures, the PIN and the backup settings are never included. The file carries a checksum so any change to it shows on this page. The checksum cannot stop someone who edits the file and recalculates it, so compare the check code with the one your client sent separately.",
  "cv.readonly": "This is a read-only view of a file: nothing can be changed or saved here.",
  "cv.notfile": "This is not a Nivesh Sahayak accountant file (.nsca).",
  "cv.iscomments": "This is a comments file. Open the books file (.nsca) first, then load comments from \"Queries and comments\".",
  "cv.newer": "This file was made by a newer version. Reload this page and try again.",
  "cv.nostore": "Could not keep your comments in this browser. Save the comments file now.",
