  "mk.sample": "ଉଦାହରଣ ଫାଇଲ୍ ଡାଉନଲୋଡ୍ କରନ୍ତୁ",
  "mk.samplec": "ପ୍ରତି ଅର୍ଡରରେ ଗୋଟିଏ ଧାଡ଼ି ଥିବା ଉଦାହରଣ? OK = ହଁ, Cancel = ପ୍ରତି ଚାର୍ଜରେ ଗୋଟିଏ ଧାଡ଼ି ଥିବା ଉଦାହରଣ।",
  "mk.start": "ମାର୍କେଟପ୍ଲେସ୍ ଆପଣଙ୍କୁ କେତେ ଦେଲା ଯାଞ୍ଚ କରନ୍ତୁ",
  "mk.starth": "ସେଲର୍ ପୋର୍ଟାଲରୁ ଡାଉନଲୋଡ୍ କରିଥିବା ପେଆଉଟ୍ (ସେଟଲମେଣ୍ଟ) ଫାଇଲ୍ Excel କିମ୍ବା CSV ଭାବେ ଖୋଲନ୍ତୁ। ଏହା କେବଳ ଏହି ବ୍ରାଉଜରରେ ପଢ଼ାଯାଏ।",
  "mk.s1": "ଫାଇଲ୍ ଖୋଲନ୍ତୁ। ଟୁଲ୍ ହେଡିଂ ଦେଖି କଲମ୍ ଖୋଜେ; କୌଣସି କଲମ୍ ଭୁଲ୍ ହେଲେ ବଦଳାନ୍ତୁ।",
  "mk.s2": "ପ୍ରତି ଅର୍ଡରକୁ ଆପଣଙ୍କ ସେଭ୍ ଇନଭଏସ୍ ସହ ଅର୍ଡର id ଦ୍ୱାରା, ତା’ପରେ ଟଙ୍କା ଓ ତାରିଖ ଦ୍ୱାରା ମିଳାଯାଏ।",
  "mk.s3": "ରିଟର୍ଣ୍ଣ, ଫି, TCS ଓ TDS, ଯେଉଁ ଅର୍ଡରର ବିଲ୍ କରିନାହାନ୍ତି, ଓ ପେଆଉଟ୍ ମେଳ ଖାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।",
  "mk.layout": "ପ୍ରତି ମାର୍କେଟପ୍ଲେସର ଫାଇଲ୍ ଲେଆଉଟ୍ ଏହି ଟୁଲ୍ ଜାଣେ ନାହିଁ ଓ ସମୟେ ସମୟେ ବଦଳେ। ଆପଣଙ୍କ ଫାଇଲ୍ ଠିକ୍ ପଢ଼ା ନ ହେଲେ, “କେଉଁ କଲମ୍ କ’ଣ” ରେ ହାତରେ କଲମ୍ ବାଛନ୍ତୁ, କିମ୍ବା ଏହା ପଢ଼ୁଥିବା ଦୁଇ ପ୍ରକାର ଦେଖିବାକୁ ଉଦାହରଣ ଫାଇଲ୍ ଡାଉନଲୋଡ୍ କରନ୍ତୁ।",
  "mk.readfail": "ଏହି ଫାଇଲ୍ ପଢ଼ି ହେଲା ନାହିଁ। Excel (.xlsx) କିମ୍ବା CSV ଫାଇଲ୍ ବ୍ୟବହାର କରନ୍ତୁ।",
