  "mk.mode.long": "ପ୍ରତି ଚାର୍ଜରେ ଗୋଟିଏ ଧାଡ଼ି, ଚାର୍ଜ ପ୍ରକାର ଓ ଗୋଟିଏ ଟଙ୍କା ସହ",
