  "mk.tdsl": "TDS (section 393 (old 194-O))",
  "mk.taxnote": "TCS ରିଟର୍ଣ୍ଣ ବାଦ୍ ଦେଇ ବିକ୍ରି ମୂଲ୍ୟ ଉପରେ, GST ବିନା ଯାଞ୍ଚ ହୁଏ। TDS ରିଟର୍ଣ୍ଣ ବାଦ୍ ଦେଇ ମୋଟ ବିକ୍ରି ଉପରେ ଯାଞ୍ଚ ହୁଏ। ଛୋଟ ବିକ୍ରେତାଙ୍କ ଅର୍ଡର TDS ରୁ ଛାଡ଼ ପାଇପାରେ ଓ ବିକ୍ରେତାଙ୍କ ପାଖରେ କମ୍ ରେଟ୍ ସର୍ଟିଫିକେଟ୍ ଥାଇପାରେ। ଦାବି କରିବା ଆଗରୁ GST ପୋର୍ଟାଲରେ TCS କ୍ରେଡିଟ୍ (TCS credit received) ଓ Form 26AS କିମ୍ବା AIS ରେ TDS ଯାଞ୍ଚ କରନ୍ତୁ।",
