  "pr.rates_pf": "ସାଧାରଣ EPF ନିୟମରୁ ସେଟ୍: ମଜୁରି ସୀମା ମାସକୁ ₹25,000 (17 Sep 2026 ରୁ), କର୍ମଚାରୀ 12%, ପେନସନ୍ (EPS) 8.33%, EDLI 0.5%, ଆଡମିନିଷ୍ଟ୍ରେସନ୍ 0.5% ସର୍ବନିମ୍ନ ₹500 ସହ। ପେମେଣ୍ଟ ଆଗରୁ EPFO ସାଇଟରେ ଯାଞ୍ଚ କରନ୍ତୁ।",
  "pr.rates_esi": "ମଜୁରିର କର୍ମଚାରୀ 0.75% ଓ ମାଲିକ 3.25%, ପ୍ରତ୍ୟେକ ପରବର୍ତ୍ତୀ ଟଙ୍କାକୁ ଉପରକୁ ରାଉଣ୍ଡ (Social Security (Central) Rules, 2026, rule 19)। ମଜୁରି ସୀମା ମାସକୁ ₹21,000: ESIC ସାଇଟରେ ଏବର ସୀମା ଯାଞ୍ଚ କରନ୍ତୁ। ଦିନ ମଜୁରି ₹176 କିମ୍ବା କମ୍ ହେଲେ କର୍ମଚାରୀ ଅଂଶ ନାହିଁ (ESIC contribution page)।",
