  "pr.pfintro": "ମାସର ସାଲାରି ସ୍ଲିପରୁ EPFO unified portal ପାଇଁ ECR ଟେକ୍ସଟ୍ ଫାଇଲ୍ ଓ ଚାଲାନ ଟଙ୍କା ତିଆରି ହୁଏ। ପ୍ରଥମେ ସ୍ଲିପ୍ ତିଆରି କରନ୍ତୁ (ସାଲାରି ଟ୍ୟାବ୍); ସ୍ଲିପ୍ ନ ଥିବା କର୍ମଚାରୀ ତଳେ ତାଲିକାରେ ଅଛନ୍ତି।",
  "pr.unver_pf": "ଅପଲୋଡ୍ ଆଗରୁ ଯାଞ୍ଚ କରନ୍ତୁ: ଏହା ତିଆରି ବେଳେ (14 Nov 2026) EPFO ର ନିଜ ଫାଇଲ୍-ଢାଞ୍ଚା ଡକ୍ୟୁମେଣ୍ଟ ଖୋଲି ହେଲା ନାହିଁ। 11ଟି ଫିଲ୍ଡ ଓ ସେମାନଙ୍କ କ୍ରମ ପେରୋଲ୍ ସଫ୍ଟୱେର୍ ତିଆରିକାରୀ ପ୍ରକାଶ କରିଥିବା ଅନୁସାରେ। ଫାଇଲ୍ EPFO ପୋର୍ଟାଲର ECR ପେଜରେ ଅପଲୋଡ୍ କରନ୍ତୁ; ପୋର୍ଟାଲ୍ କୌଣସି ଲାଇନ୍ ନାକଚ କଲେ କାରଣ କହେ।",
