  "pr.chnote": "{m}ଜଣ ସଦସ୍ୟଙ୍କ ପାଇଁ। ପରବର୍ତ୍ତୀ ମାସର {d} ତାରିଖ ଭିତରେ ଦେବାକୁ; ବିଳମ୍ବରେ ସୁଧ ଓ ଡ୍ୟାମେଜ୍ ଯୋଡାଯାଏ। ପୋର୍ଟାଲ୍ ଅପଲୋଡ୍ ଫାଇଲରୁ ଚାଲାନ ତିଆରି କରି ଶେଷ ହିସାବ ଦେଖାଏ: ଏହି ହିସାବ ସହ ମିଳାନ୍ତୁ।",
  "pr.esiintro": "ମାସର ସାଲାରି ସ୍ଲିପରୁ ESIC employer portal ପାଇଁ ମାସିକ କଣ୍ଟ୍ରିବ୍ୟୁସନ୍ ସିଟ୍ ଓ ଚାଲାନ ଟଙ୍କା ତିଆରି ହୁଏ। କେବଳ ଯେଉଁ କର୍ମଚାରୀଙ୍କ ଦରମା ମଜୁରି ସୀମା ଭିତରେ (କିମ୍ବା ସେହି ଅଧା ବର୍ଷରେ ଆଗରୁ କଭର୍ ହୋଇଥିଲେ) ସେମାନେ ଫାଇଲରେ ଅଛନ୍ତି।",
  "pr.unver_esi": "ଏହି ସିଟ୍ ESIC ପୋର୍ଟାଲର ନିଜ Monthly Contribution ଟେମ୍ପଲେଟ୍ ଅନୁସାରେ (15 Nov 2026 ରେ ଯାଞ୍ଚ): ଛଅଟି ଟେକ୍ସଟ୍ କଲମ୍, Excel 97-2003 (.xls) ଭାବେ ସେଭ୍। ଏହି ମାସରେ ମଜୁରି ନ ଥିବା କର୍ମଚାରୀ ମଧ୍ୟ କାରଣ କୋଡ୍ ସହ ଅଛନ୍ତି। ପ୍ରଥମେ ଗୋଟିଏ ମାସ ଅପଲୋଡ୍ କରି ପୋର୍ଟାଲର ଫଳାଫଳ ଦେଖନ୍ତୁ।",
