  "it.m_senior": "ବିଜନେସ୍ କିମ୍ବା ପ୍ରଫେସନାଲ୍ ଆୟ ନ ଥିବା 60 କିମ୍ବା ଅଧିକ ବୟସର ବାସିନ୍ଦା ଆଡଭାନ୍ସ ଟ୍ୟାକ୍ସ ଦିଅନ୍ତି ନାହିଁ (section 403(3))। ରିଟର୍ଣ୍ଣ ଫାଇଲ୍ ବେଳେ ବାକି ଦିଅନ୍ତୁ।",
  "it.m_below": "TDS ପରେ ଟ୍ୟାକ୍ସ {n}, ₹10,000 ତଳେ, ତେଣୁ ଆଡଭାନ୍ସ ଟ୍ୟାକ୍ସ ଦେବାକୁ ନାହିଁ (section 404)। ରିଟର୍ଣ୍ଣ ଫାଇଲ୍ ବେଳେ ବାକି ଦିଅନ୍ତୁ।",
