  "it.m_sur": "ଆପଣଙ୍କ ଆୟ ₹50 ଲକ୍ଷରୁ ଅଧିକ: ସରଚାର୍ଜ ଲେଖନ୍ତୁ, ଏଠାରେ ହିସାବ ହୁଏ ନାହିଁ।",
  "it.m_past": "ଏହି ବର୍ଷ ଶେଷ ହୋଇଗଲାଣି। 31 March ପରେ ଦିଆଯାଇଥିବା ଆଡଭାନ୍ସ ଟ୍ୟାକ୍ସ ଏହାର ଆଡଭାନ୍ସ ଟ୍ୟାକ୍ସ ଭାବେ ଗଣାଯାଏ ନାହିଁ; ତଳର ସୁଧ କମ୍ ଦେଲେ କେତେ ଲାଗିବ ଦେଖାଏ।",
  "it.m_season": "ଆନ୍ଦାଜ ଏପର୍ଯ୍ୟନ୍ତର ଲାଭକୁ ସିଧା ଭାବେ ପୂରା ବର୍ଷକୁ ନିଏ। ଆପଣଙ୍କ ବିଜନେସ୍ ସିଜନାଲ୍ ହେଲେ ବର୍ଷର ନିଜ ସଂଖ୍ୟା ଲେଖନ୍ତୁ।",
