  "it.basis": "ଏହି ସଂଖ୍ୟା କେଉଁ ଆଧାରରେ ({d} ସୁଦ୍ଧା)",
  "it.b1": "ରେଟ୍ ({d} ସୁଦ୍ଧା), ଟ୍ୟାକ୍ସ ବର୍ଷ 2026-27: ନୂଆ ରିଜିମ୍ ₹4 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ ଶୂନ, ₹8 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 5%, ₹12 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 10%, ₹16 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 15%, ₹20 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 20%, ₹24 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 25%, ତା’ଠାରୁ ଅଧିକ 30%; ₹12 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ ଆୟରେ ଟ୍ୟାକ୍ସ ନ ଲାଗିବା ଭଳି ରିବେଟ୍, ଟିକିଏ ଅଧିକରେ ମାର୍ଜିନାଲ୍ ରିଲିଫ୍ ସହ; ସାଲାରି ଉପରେ ଷ୍ଟାଣ୍ଡାର୍ଡ ଡିଡକ୍ସନ୍ ₹75,000। ପୁରୁଣା ରିଜିମ୍: ₹2.5 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ ଶୂନ (60ରେ ₹3 ଲକ୍ଷ, 80ରେ ₹5 ଲକ୍ଷ), ₹5 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 5%, ₹10 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 20%, ତା’ଠାରୁ ଅଧିକ 30%; ₹5 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ ରିବେଟ୍ ₹12,500; ଷ୍ଟାଣ୍ଡାର୍ଡ ଡିଡକ୍ସନ୍ ₹50,000। ଏଗୁଡ଼ିକ ସାଲାରି ସ୍ଲିପ୍ ଟୁଲ୍ ଆଗରୁ ବ୍ୟବହାର କରୁଥିବା ରେଟ୍; ଏହି ବିଲ୍ଡରେ Finance Act ରୁ ପୁଣି ପଢ଼ାଯାଇନାହିଁ, ତେଣୁ ଯାଞ୍ଚ କରନ୍ତୁ।",
  "it.b2": "ଆଡଭାନ୍ସ ଟ୍ୟାକ୍ସ (Income-tax Act 2025, sections 403 ରୁ 408): TDS ପରେ ଟ୍ୟାକ୍ସ ₹10,000 କିମ୍ବା ଅଧିକ ହେଲେ ଦେବାକୁ; 15 June ଭିତରେ 15%, 15 September ଭିତରେ 45%, 15 December ଭିତରେ 75%, 15 March ଭିତରେ ସବୁ; ପ୍ରିଜମ୍ପଟିଭ୍ ଟ୍ୟାକ୍ସପେୟର 15 March ଭିତରେ ସବୁ ଦିଅନ୍ତି; 31 March ପର୍ଯ୍ୟନ୍ତ ଦେଲେ ସେହି ବର୍ଷ ପାଇଁ ଗଣାଯାଏ; ବିଜନେସ୍ ଆୟ ନ ଥିବା 60 କିମ୍ବା ଅଧିକ ବୟସର ବାସିନ୍ଦାଙ୍କୁ ଛାଡ଼।",
  "it.b3": "ସୁଧ: section 424 (ପୁରୁଣା 234B) ଟ୍ୟାକ୍ସର 90%ରୁ କମ୍ ଦେଲେ କମ୍ ଟଙ୍କା ଉପରେ ପ୍ରତି ମାସ କିମ୍ବା ମାସର ଅଂଶ ପାଇଁ 1%; section 425 (ପୁରୁଣା 234C) ପ୍ରଥମ ତିନି କିସ୍ତିର ପ୍ରତ୍ୟେକ କମ୍ ଉପରେ 3% (15 June ଭିତରେ 12% ଓ 15 September ଭିତରେ 36% ଦେଇଥିଲେ ନାହିଁ) ଓ March କମ୍ ଉପରେ 1%।",
  "it.b4": "ଉପରର sections 15 Nov 2026 ରେ Income Tax Department ର ୱେବସାଇଟ୍ (incometaxindia.gov.in) ର ସରକାରୀ ଲେଖା ସହ ଶବ୍ଦ ଶବ୍ଦ ଯାଞ୍ଚ ହୋଇଥିଲା। ପ୍ରିଣ୍ଟ ହୋଇଥିବା Act ହିଁ ଶେଷ କଥା।",
  "it.b5": "ଖାତାର ଲାଭ ଟ୍ୟାକ୍ସେବଲ୍ ଲାଭ ନୁହେଁ: Act ଅନୁସାରେ ଡିପ୍ରିସିଏସନ୍, ମନା ହୋଇଥିବା ଖର୍ଚ୍ଚ ଓ ପ୍ରିଜମ୍ପଟିଭ୍ ନିୟମ ଏହାକୁ ବଦଳାଏ। ଏହି ପ୍ଲାନ୍ ଓ ଡାଟା ସିଟ୍ ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ଦିଅନ୍ତୁ।",
  "it.b6": "ହିସାବ ହୁଏ ନାହିଁ: ସରଚାର୍ଜ, ସ୍ୱତନ୍ତ୍ର ରେଟରେ କ୍ୟାପିଟାଲ୍ ଗେନ୍, ବିଦେଶୀ ଟ୍ୟାକ୍ସ ରିଲିଫ୍, ନାବାଳକଙ୍କ ଆୟ ଉପରେ ଟ୍ୟାକ୍ସ, ଓ ବିଳମ୍ବ ଫାଇଲିଂର ସୁଧ।",
  "it.b7": "କିଛି ଫାଇଲ୍ ହୁଏ ନାହିଁ ଓ ଆପଣଙ୍କ ଖାତାରେ କିଛି ଲେଖାଯାଏ ନାହିଁ।",
  "it.itr_h": "କେଉଁ ରିଟର୍ଣ୍ଣ ଫର୍ମ ଠିକ୍, କାହିଁକି, ଓ କେଉଁ କାଗଜପତ୍ର ପ୍ରସ୍ତୁତ ରଖିବେ ଦେଖିବାକୁ କିଛି ପ୍ରଶ୍ନର ଉତ୍ତର ଦିଅନ୍ତୁ।",
