  "it.q_esop": "ମୋର ମାଲିକଙ୍କ ସେୟାର୍ (ESOP) ଉପରେ ଡିଫର୍ଡ ଟ୍ୟାକ୍ସ ଅଛି",
  "it.q_crypto": "ମୁଁ crypto ଭଳି ଭର୍ଚୁଆଲ୍ ଡିଜିଟାଲ୍ ସମ୍ପତ୍ତି ବିକ୍ରି କରିଛି",
  "it.formd_ITR-1": "ସାଲାରି କିମ୍ବା ପେନସନ୍, ଦୁଇଟି ପର୍ଯ୍ୟନ୍ତ ଘର ସମ୍ପତ୍ତି ଓ ସୁଧ ଭଳି ଅନ୍ୟ ଉତ୍ସ, ଓ ₹50 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ ମୋଟ ଆୟ ଥିବା ବାସିନ୍ଦା ବ୍ୟକ୍ତିଙ୍କ ପାଇଁ।",
