  "it.w_simple": "ସୀମା ଭିତରେ କେବଳ ସାଲାରି, ଘର ସମ୍ପତ୍ତି ଓ ସୁଧ ITR-1 ରେ ଖାପ ଖାଏ।",
  "it.n_forms": "ସର୍ତ୍ତ 31 March 2026 ରେ ଶେଷ ହୋଇଥିବା ବର୍ଷ ପାଇଁ ବିଜ୍ଞପ୍ତି ହୋଇଥିବା ରିଟର୍ଣ୍ଣ ଅନୁସାରେ (ଟ୍ୟାକ୍ସ ପୋର୍ଟାଲ୍ ଅନୁସାରେ ITR-1 ଓ ITR-4 ଏବେ ଦୁଇଟି ପର୍ଯ୍ୟନ୍ତ ଘର ସମ୍ପତ୍ତି ଅନୁମତି ଦିଏ)। ଟ୍ୟାକ୍ସ ବର୍ଷ 2026-27 ର ରିଟର୍ଣ୍ଣ Income-tax Rules, 2026 ରେ ଏବେ ବି ବିଜ୍ଞପ୍ତି ହେବାକୁ ବାକି: ଫାଇଲ୍ ଆଗରୁ ଫର୍ମର ନିଜ “କିଏ ବ୍ୟବହାର କରିପାରିବେ ନାହିଁ” ତାଲିକା ପଢ଼ନ୍ତୁ।",
  "it.n_ltcg": "ଲିଷ୍ଟେଡ୍ ସେୟାର୍ କିମ୍ବା ଇକ୍ୱିଟି ଫଣ୍ଡରେ ଛୋଟ ଦୀର୍ଘକାଳୀନ ଗେନ୍ କିଛି ବର୍ଷ ITR-1 ଓ ITR-4 ରେ ଅନୁମତି ଥିଲା; 2026-27 ପାଇଁ ଏହା ନିଶ୍ଚିତ ହୋଇନାହିଁ, ତେଣୁ ITR-2 ସୁରକ୍ଷିତ ପସନ୍ଦ ଓ ଫର୍ମର ନିଜ ତାଲିକା ହିଁ ଶେଷ କଥା।",
