  "bi.postfail": "ପୋଷ୍ଟିଂ ଅଧା ବାଟରେ ବନ୍ଦ ହେଲା। ଷ୍ଟେଟମେଣ୍ଟ ପୁଣି ଖୋଲନ୍ତୁ: ଆଗରୁ ପୋଷ୍ଟ ହୋଇଥିବା ଲାଇନ୍ ଦୁଇଥର ପୋଷ୍ଟ ହୁଏ ନାହିଁ।",
  "bi.remember": "ଗୋଟିଏ ଲାଇନ୍ ପାଇଁ ଆପଣ ନିଶ୍ଚିତ କରୁଥିବା ପାର୍ଟି କିମ୍ବା ହେଡ୍ ମନେ ରଖାଯାଏ ଓ ପରଥର ଷ୍ଟେଟମେଣ୍ଟରେ ସେହି ନାମ ଆସିଲେ ପରାମର୍ଶ ଦିଆଯାଏ।",
  "nav.ca": "ଆକାଉଣ୍ଟାଣ୍ଟ ଭ୍ୟୁଅର୍",
  "ca.mk": "ମୋ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କ ପାଇଁ ଫାଇଲ୍ ତିଆରି କରନ୍ତୁ (କେବଳ ପଢ଼ିବା ପାଇଁ)",
  "ca.t": "ମୋ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କ ପାଇଁ ଫାଇଲ୍",
  "ca.intro": "ଗୋଟିଏ ବିଜନେସ୍ ଓ ସମୟକୁ ଗୋଟିଏ କେବଳ-ପଢ଼ିବା ଫାଇଲ୍ (.nsca) ରେ ପ୍ୟାକ୍ କରେ। ଏହାକୁ WhatsApp କିମ୍ବା ଇମେଲରେ ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ପଠାନ୍ତୁ। ସେମାନେ ca.niveshsahayak.in ରେ ଖୋଲି ଖାତା ପଢ଼ନ୍ତି, ପ୍ରଶ୍ନ ଯୋଡନ୍ତି ଓ ଆପଣଙ୍କୁ ମନ୍ତବ୍ୟ ଫେରାଇ ପଠାନ୍ତି।",
  "ca.notlive": "ଏହା ଫାଇଲ୍ ଦେବା, ଲାଇଭ୍ ସାଝା ଲଗଇନ୍ ନୁହେଁ। ଫାଇଲ୍ ତିଆରି ବେଳେ ଖାତା ଯେମିତି ଥିଲା ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟ ସେମିତି ଦେଖନ୍ତି। ଲାଇଭ୍ ଲଗଇନ୍ ପାଇଁ ଆପଣଙ୍କ ଖାତା ରଖୁଥିବା ସର୍ଭର ଦରକାର, ଓ Nivesh Sahayak ର କୌଣସି ସର୍ଭର ନାହିଁ: ଆପଣଙ୍କ ଖାତା ଆପଣଙ୍କ ଡିଭାଇସରେ ରହେ। ନୂଆ ଏଣ୍ଟ୍ରି ପାଇଁ ନୂଆ ଫାଇଲ୍ ତିଆରି କରନ୍ତୁ।",
  "ca.what": "କ’ଣ ଯାଏ",
  "ca.earlier": "ପ୍ରଥମ ତାରିଖ ଆଗର ଏଣ୍ଟ୍ରି ମଧ୍ୟ (ପୁରୁଣା ବାଲାନ୍ସ ଓ ଏଜିଂ ପାଇଁ ଦରକାର)",
  "ca.items": "କିଣା ଓ ବିକ୍ରି ରେଟ୍ ସହ ଆଇଟମ୍ ତାଲିକା (ଷ୍ଟକ୍ ପାଇଁ ଦରକାର)",
  "ca.extra": "କେବଳ ଟିକ୍ କଲେ",
  "ca.extrah": "ଟିକ୍ ନ କଲେ ଛାଡ଼ି ଦିଆଯାଏ। ଫଟୋ (ଲୋଗୋ, ସିଗ୍ନେଚର୍), ଆପଣଙ୍କ PIN ଓ ବ୍ୟାକଅପ୍ ସେଟିଂ କେବେ ବି ଯାଏ ନାହିଁ।",
