  "ca.code": "ଯାଞ୍ଚ କୋଡ୍:",
  "ca.codeh": "ଏହି କୋଡ୍ ଆପଣଙ୍କ ମେସେଜରେ ପଠାନ୍ତୁ, କିମ୍ବା କଲରେ ପଢ଼ି ଶୁଣାନ୍ତୁ। ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟ ଫାଇଲ୍ ଦେଖାଉଥିବା କୋଡ୍ ସହ ମିଳାନ୍ତି, ତେଣୁ ବାଟରେ ବଦଳିଥିବା ଫାଇଲ୍ ଜଣାପଡ଼େ।",
