  "ca.msg": "{biz}ର {from} ରୁ {to} ପର୍ଯ୍ୟନ୍ତ ଖାତା। ସଂଲଗ୍ନ ଫାଇଲ୍ {url} ରେ ଖୋଲନ୍ତୁ (ଲଗଇନ୍ ବିନା ଚାଲେ, କିଛି ଅପଲୋଡ୍ ହୁଏ ନାହିଁ)। ଯାଞ୍ଚ କୋଡ୍: {code}। ଏହା ଆଜି ତିଆରି କେବଳ-ପଢ଼ିବା କପି; ଦୟାକରି ଆପଣଙ୍କ ପ୍ରଶ୍ନ ମନ୍ତବ୍ୟ ଫାଇଲ୍ ଭାବେ ଫେରାଇ ପଠାନ୍ତୁ।",
  "ca.how": "ଫାଇଲ୍ WhatsApp କିମ୍ବା ଇମେଲରେ ସଂଲଗ୍ନ ଭାବେ ପଠାନ୍ତୁ। WhatsApp ନାମ ଶେଷରେ .nsca ଦେଖାଇଲେ ନାମ ବଦଳାନ୍ତୁ ନାହିଁ।",
  "ca.cT": "CA ମନ୍ତବ୍ୟ",
  "ca.cIntro": "ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟ ପ୍ରଶ୍ନ ଓ ମନ୍ତବ୍ୟର ଛୋଟ ଫାଇଲ୍ (.nsca-comments) ଫେରାଇ ପଠାନ୍ତି। ପ୍ରତି ପ୍ରଶ୍ନ ତା’ର ଏଣ୍ଟ୍ରି ପାଖରେ ଦେଖିବାକୁ ଏଠାରେ ଲୋଡ୍ କରନ୍ତୁ। ଉତ୍ତର ଦିଅନ୍ତୁ, ବନ୍ଦ ଚିହ୍ନିତ କରନ୍ତୁ, ଓ ଫେରାଇ ପଠାଇବାକୁ ଫାଇଲ୍ ପୁଣି ସେଭ୍ କରନ୍ତୁ।",
  "ca.load": "ମନ୍ତବ୍ୟ ଫାଇଲ୍ ଲୋଡ୍ କରନ୍ତୁ",
  "ca.export": "ମୋ ଉତ୍ତର ସହ ଫାଇଲ୍ ସେଭ୍ କରନ୍ତୁ",
