  "ca.badfile": "ଏହା ଆକାଉଣ୍ଟାଣ୍ଟ ଭ୍ୟୁଅରର ମନ୍ତବ୍ୟ ଫାଇଲ୍ ନୁହେଁ, କିମ୍ବା ଏହା ବଦଳାଯାଇଛି।",
