  "ca.screen": "ସ୍କ୍ରିନ୍",
  "ca.general": "ସାଧାରଣ ମନ୍ତବ୍ୟ",
  "cv.h1": "ଆକାଉଣ୍ଟାଣ୍ଟ ଭ୍ୟୁଅର୍: ଆପଣଙ୍କ କ୍ଲାଏଣ୍ଟ ପଠାଇଥିବା ଖାତା ଫାଇଲ୍ ଖୋଲନ୍ତୁ",
  "cv.intro": "ଆପଣଙ୍କ କ୍ଲାଏଣ୍ଟ ଗୋଟିଏ ସମୟର ଖାତା ଗୋଟିଏ ଫାଇଲରେ ପ୍ୟାକ୍ କରି WhatsApp କିମ୍ବା ଇମେଲରେ ଆପଣଙ୍କୁ ପଠାନ୍ତି। ଏଠାରେ ଖୋଲି ପଢ଼ନ୍ତୁ: ବାକି, ପାର୍ଟି, ଲେଜର୍, ଡେ ବୁକ୍, GST ହିସାବ, ଫାଇନାଲ୍ ଆକାଉଣ୍ଟ ଓ ପ୍ରତି ଡକ୍ୟୁମେଣ୍ଟ। ଖୋଜନ୍ତୁ ଓ ଫିଲ୍ଟର କରନ୍ତୁ, ଯେକୌଣସି ଏଣ୍ଟ୍ରିରେ ପ୍ରଶ୍ନ ପଚାରନ୍ତୁ, ଓ ଆପଣଙ୍କ ମନ୍ତବ୍ୟ ଛୋଟ ଫାଇଲ୍ ଭାବେ ଫେରାଇ ପଠାନ୍ତୁ। ମାଗଣା, ଲଗଇନ୍ ନାହିଁ, କିଛି ଅପଲୋଡ୍ ହୁଏ ନାହିଁ: ଫାଇଲ୍ ଆପଣଙ୍କ ବ୍ରାଉଜର ଭିତରେ ପଢ଼ାଯାଏ।",
  "cv.drop": ".nsca ଫାଇଲ୍ ଏଠାରେ ପକାନ୍ତୁ",
  "cv.choose": "ଫାଇଲ୍ ବାଛନ୍ତୁ",
  "cv.dropnote": "ଫାଇଲ୍ ଏହି ଡିଭାଇସରେ ରହେ। ଏଠାରେ କିଛି ସେଭ୍ ହୁଏ ନାହିଁ ଓ ଆପଣ ଏଠାରୁ କ୍ଲାଏଣ୍ଟଙ୍କ ଖାତା ବଦଳାଇ ପାରିବେ ନାହିଁ।",
  "cv.nav.home": "ସାରାଂଶ",
  "cv.docs": "ଡକ୍ୟୁମେଣ୍ଟ",
  "cv.day": "ଡେ ବୁକ୍",
  "cv.fin": "ଫାଇନାଲ୍ ଆକାଉଣ୍ଟ",
  "cv.gst": "GST ହିସାବ",
  "cv.cT": "ପ୍ରଶ୍ନ ଓ ମନ୍ତବ୍ୟ",
  "cv.how.h": "ଏହା କିପରି କାମ କରେ",
  "cv.how.1": "ଆପଣଙ୍କ କ୍ଲାଏଣ୍ଟ Nivesh Sahayak ଖୋଲି, ମୋ ଡାଟା, ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ପଠାନ୍ତୁ କୁ ଯାଇ, ଗୋଟିଏ ବିଜନେସ୍ ଓ ସମୟ ପାଇଁ \"ମୋ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କ ପାଇଁ ଫାଇଲ୍ ତିଆରି କରନ୍ତୁ\" ବାଛନ୍ତି।",
  "cv.how.2": "ସେମାନେ ଆପଣଙ୍କୁ ଫାଇଲ୍ (.nsca ରେ ଶେଷ) ଓ ସେହି ମେସେଜରେ ଗୋଟିଏ ଛୋଟ ଯାଞ୍ଚ କୋଡ୍ ପଠାନ୍ତି।",
  "cv.how.3": "ଆପଣ ଏହି ପେଜରେ ଫାଇଲ୍ ଖୋଲନ୍ତି। ଫାଇଲ୍ ବଦଳିଛି କି ନାହିଁ ପେଜ୍ କହେ ଓ କ୍ଲାଏଣ୍ଟ ଦେଇଥିବା ଯାଞ୍ଚ କୋଡ୍ ଲେଖି ମିଳାଇବାକୁ ଦିଏ।",
  "cv.how.4": "ଖାତା ପଢ଼ନ୍ତୁ, ଖୋଜନ୍ତୁ, ଓ ଯେକୌଣସି ଡକ୍ୟୁମେଣ୍ଟ, ଡେ ବୁକ୍ ଏଣ୍ଟ୍ରି କିମ୍ବା ସ୍କ୍ରିନରେ \"ପ୍ରଶ୍ନ କିମ୍ବା ମନ୍ତବ୍ୟ ଯୋଡନ୍ତୁ\" ଦବାନ୍ତୁ। ଆପଣ ଲେଖୁଥିବା ସବୁ ଏହି ବ୍ରାଉଜରରେ ରହେ।",
  "cv.how.5": "ସରିଗଲେ \"ପ୍ରଶ୍ନ ଓ ମନ୍ତବ୍ୟ\" ଖୋଲି ଛୋଟ .nsca-comments ଫାଇଲ୍ ଫେରାଇ ପଠାନ୍ତୁ। ଆପଣଙ୍କ କ୍ଲାଏଣ୍ଟ ଏହାକୁ ଲୋଡ୍ କରି ପ୍ରତି ପ୍ରଶ୍ନ ଏଣ୍ଟ୍ରି ପାଖରେ ଦେଖନ୍ତି। ସେମାନେ ଉତ୍ତର ଦେଇପାରନ୍ତି, ଓ ଆପଣ ଉତ୍ତର ଏଠାରେ ଲୋଡ୍ କରିପାରିବେ।",
  "cv.live.h": "ଫାଇଲ୍ ଦେବା, ଲାଇଭ୍ ଲଗଇନ୍ ନୁହେଁ",
  "cv.live.p": "ଏହା ଫାଇଲ୍ ଦେବା। ଆପଣ କ୍ଲାଏଣ୍ଟଙ୍କ ଆକାଉଣ୍ଟରେ ଲଗଇନ୍ କରନ୍ତି ନାହିଁ ଓ ସେମାନେ ପରେ କରୁଥିବା ବଦଳ ଦେଖନ୍ତି ନାହିଁ। ଲାଇଭ୍ ସାଝା ଲଗଇନ୍ ପାଇଁ ଖାତା ରଖୁଥିବା ସର୍ଭର ଦରକାର, ଓ Nivesh Sahayak ର କୌଣସି ସର୍ଭର ନାହିଁ: ଖାତା କ୍ଲାଏଣ୍ଟଙ୍କ ଡିଭାଇସରେ ରହେ। ନୂଆ ସମୟ ପାଇଁ କିମ୍ବା ସଂଶୋଧନ ପରେ କ୍ଲାଏଣ୍ଟଙ୍କଠାରୁ ନୂଆ ଫାଇଲ୍ ମାଗନ୍ତୁ।",
  "cv.safe.h": "ଫାଇଲରେ କ’ଣ ଅଛି, ଓ କ’ଣ ନାହିଁ",
  "cv.safe.p": "କ’ଣ ଯିବ ଆପଣଙ୍କ କ୍ଲାଏଣ୍ଟ ଟିକ୍ କରନ୍ତି। ସାଧାରଣତଃ ଫାଇଲରେ ଗୋଟିଏ ବିଜନେସର ସମୟ ଶେଷ ପର୍ଯ୍ୟନ୍ତ ଏଣ୍ଟ୍ରି, ପାର୍ଟି ଓ ଆଇଟମ୍ ଥାଏ। କୋଟେସନ ଓ ଅର୍ଡର, ସାଲାରି ଓ ଷ୍ଟାଫ୍ ରେକର୍ଡ, ଫୋନ୍ ନମ୍ବର ଓ ଇମେଲ ଠିକଣା, ଓ ବିଜନେସର ବ୍ୟାଙ୍କ ଆକାଉଣ୍ଟ ବିବରଣୀ କ୍ଲାଏଣ୍ଟ ଟିକ୍ ନ କଲେ ଛାଡ଼ି ଦିଆଯାଏ। ଫଟୋ, PIN ଓ ବ୍ୟାକଅପ୍ ସେଟିଂ କେବେ ବି ଯାଏ ନାହିଁ। ଫାଇଲରେ ଚେକସମ୍ ଥାଏ, ତେଣୁ ଯେକୌଣସି ବଦଳ ଏହି ପେଜରେ ଦେଖାଯାଏ। ଫାଇଲ୍ ବଦଳାଇ ଚେକସମ୍ ପୁଣି ହିସାବ କରୁଥିବା ଲୋକଙ୍କୁ ଚେକସମ୍ ରୋକିପାରେ ନାହିଁ, ତେଣୁ କ୍ଲାଏଣ୍ଟ ଅଲଗାରେ ପଠାଇଥିବା ଯାଞ୍ଚ କୋଡ୍ ସହ ମିଳାନ୍ତୁ।",
  "cv.readonly": "ଏହା ଗୋଟିଏ ଫାଇଲର କେବଳ-ପଢ଼ିବା ଦୃଶ୍ୟ: ଏଠାରେ କିଛି ବଦଳାଯାଇ କିମ୍ବା ସେଭ୍ କରାଯାଇ ପାରିବ ନାହିଁ।",
  "cv.notfile": "ଏହା Nivesh Sahayak ଆକାଉଣ୍ଟାଣ୍ଟ ଫାଇଲ୍ (.nsca) ନୁହେଁ।",
  "cv.iscomments": "ଏହା ଗୋଟିଏ ମନ୍ତବ୍ୟ ଫାଇଲ୍। ପ୍ରଥମେ ଖାତା ଫାଇଲ୍ (.nsca) ଖୋଲନ୍ତୁ, ତା’ପରେ \"ପ୍ରଶ୍ନ ଓ ମନ୍ତବ୍ୟ\" ରୁ ମନ୍ତବ୍ୟ ଲୋଡ୍ କରନ୍ତୁ।",
