  "hm.h.creep.low": "ଖର୍ଚ୍ଚ ହଠାତ୍ ବଢ଼ିଲା। ବଢ଼ିଥିବା ହେଡ୍ ଖୋଜନ୍ତୁ ଓ ଏହା ଥରକର ବିଲ୍ ନୁହେଁ କି ଯାଞ୍ଚ କରନ୍ତୁ।",
  "hm.h.creep.rule": "ଗତ ପୂରା ମାସର ଖର୍ଚ୍ଚ ତା’ ଆଗର 3 ମାସର ହାରାହାରି ତୁଳନାରେ। 5% କିମ୍ବା କମ୍ ବଢ଼ିଲେ 100, 40% କିମ୍ବା ଅଧିକ ବଢ଼ିଲେ 0। ଥରକର ବଡ଼ ବିଲ୍ ଗୋଟିଏ ମାସ ପାଇଁ ଏହାକୁ କମାଇବ।",
