  "hm.rm.title": "{b}: ଆଜି ଆପଣଙ୍କୁ ଦରକାର",
  "hm.rm.ics": "ଦେବା ତାରିଖ ଆପଣଙ୍କ ଫୋନ୍ କ୍ୟାଲେଣ୍ଡରରେ ରଖନ୍ତୁ",
  "hm.rm.icsp": "ଆସନ୍ତା 60 ଦିନର କ୍ୟାଲେଣ୍ଡର ଫାଇଲ୍ ତିଆରି କରେ: ବିଲ୍ ଦେବା ତାରିଖ ଓ ଟ୍ୟାକ୍ସ ତାରିଖ। ଆପଣଙ୍କ ନିଜ କ୍ୟାଲେଣ୍ଡରରେ ଯୋଡିବାକୁ ଫୋନରେ ଖୋଲନ୍ତୁ, ଯାହା ଏହି App ବନ୍ଦ ଥିଲେ ମଧ୍ୟ ଦିନେ ଆଗରୁ ନିଜେ ବାଜେ।",
  "hm.rm.icsgo": "କ୍ୟାଲେଣ୍ଡର ଫାଇଲ୍ ତିଆରି କରନ୍ତୁ",
  "hm.rm.icsnone": "ଆସନ୍ତା 60 ଦିନରେ କ୍ୟାଲେଣ୍ଡରରେ ରଖିବାକୁ କୌଣସି ଦେବା ତାରିଖ ନାହିଁ।",
  "hm.rm.icsdone": "{n}ଟି ତାରିଖ ସହ କ୍ୟାଲେଣ୍ଡର ଫାଇଲ୍ ତିଆରି। ଯୋଡିବାକୁ ଏହାକୁ ଖୋଲନ୍ତୁ।",
  "hm.rm.recv": "ଅସୁଲ କରନ୍ତୁ",
  "hm.rm.pay": "ଦିଅନ୍ତୁ",
  "hm.rm.lim": "ବ୍ରାଉଜର କ’ଣ କରିପାରେ ନାହିଁ",
  "hm.rm.l1": "ୱେବ୍ ପେଜ୍ ବନ୍ଦ ଥିଲେ ଚାଲିପାରେ ନାହିଁ, ଓ ଆପଣଙ୍କୁ ପୁସ୍ ମେସେଜ୍ ପଠାଇବାକୁ ଏହି App ପଛରେ କୌଣସି ସର୍ଭର ନାହିଁ। ତେଣୁ App ର ରିମାଇଣ୍ଡର କେବଳ App ଖୋଲିଲେ ଦେଖାଯାଏ।",
  "hm.rm.l2": "ସବୁ ଆପଣଙ୍କ ଡିଭାଇସରେ ହିସାବ ହୁଏ, ତେଣୁ ଇଣ୍ଟରନେଟ୍ ବିନା ଚାଲେ। ଆପଣଙ୍କ ବିଜନେସ୍ ବିଷୟରେ କିଛି କେଉଁଠି ପଠାଯାଏ ନାହିଁ।",
  "hm.rm.l3": "ଯେଉଁ ତାରିଖ ଭୁଲିବା ଉଚିତ ନୁହେଁ ସେଥିପାଇଁ କ୍ୟାଲେଣ୍ଡର ଫାଇଲ୍ ବ୍ୟବହାର କରନ୍ତୁ: ଆପଣଙ୍କ ଫୋନ୍ କ୍ୟାଲେଣ୍ଡର ନିଜେ ବାଜେ। ଏହା ଆଜିର ଛବି, ତେଣୁ ନୂଆ ବିଲ୍ ଲେଖିବା ପରେ ନୂଆ ଫାଇଲ୍ ତିଆରି କରନ୍ତୁ।",
  "hm.rm.l4": "ଇନଷ୍ଟଲ୍ ହୋଇଥିବା App ରେ ଆଇକନର ସଂଖ୍ୟା କେତେ ଜରୁରୀ କଥା ଅଛି ଦେଖାଏ, ଯେଉଁଠି ଆପଣଙ୍କ ଫୋନ୍ ଅନୁମତି ଦିଏ।",
