  "cp.lim_p": "Your own sales for this financial year and the last one, without tax, against the limits that decide the composition scheme, e-invoice and e-way bill. Only the sales of this business saved in the App are counted. The law counts every GSTIN under one PAN together, and other kinds of turnover too, so check with your CA.",
